import { getAllProducts } from '@/lib/db';

export default async function Page() {
  const products = await getAllProducts();

  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <main style={{ fontFamily: 'sans-serif', maxWidth: 800, margin: '2rem auto', padding: '0 1rem' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.5rem' }}>
        <h1 style={{ margin: 0 }}>Product Catalog</h1>
        <form action={syncCatalog}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #ccc', textAlign: 'left' }}>
            <th style={{ padding: '0.5rem 1rem' }}>ID</th>
            <th style={{ padding: '0.5rem 1rem' }}>Name</th>
            <th style={{ padding: '0.5rem 1rem' }}>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product: { id: number; name: string; price: number }) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: '0.5rem 1rem' }}>{product.id}</td>
              <td style={{ padding: '0.5rem 1rem' }}>{product.name}</td>
              <td style={{ padding: '0.5rem 1rem' }}>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  );
}
